// TouchLine Edge Function touchline-e__ENGINE__, the loader form (deploy with Verify JWT on). The engine, the verifier
// and the request flow live in one hashed bundle the site publishes with every build (dist/edge/verifier-<hash16>.js,
// scripts/online/edgeBundle.mjs); this file fetches it from the live site, refuses anything whose SHA-256 is not the
// constant below, runs it once per isolate and hands it each verified request. A compromised or stale site cannot change
// what runs here: a new engine or bundle needs a new deploy with a new hash. Generated by
// scripts/online/build-loader.mjs from supabase/functions/touchline/loader.ts; no key is in it (the platform injects
// SUPABASE_URL, the keys and the JWKS).
import 'npm:@supabase/supabase-js@__SUPABASE_JS__'
import { withSupabase } from 'npm:@supabase/server@__SUPABASE_SERVER__'

const ENGINE = '__ENGINE__'
const VERIFIER_SHA256 = '__VERIFIER_SHA256__'
const SITE = (Deno.env.get('TOUCHLINE_SITE_URL') ?? 'https://touchline.quest').replace(/\/+$/, '')
const URL_ = `${SITE}/edge/verifier-${VERIFIER_SHA256.slice(0, 16)}.js`
const GLOBAL = '__touchlineEdge'

type Handler = (req: Request, ctx: unknown) => Promise<Response>
interface Edge {
  ENGINE_VERSION: string
  createEdgeHandler(opts: { site: string }): Handler
}

const log = (line: Record<string, unknown>) => console.log(JSON.stringify({ fn: `touchline-e${ENGINE}`, ...line }))

async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const d = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes as BufferSource))
  return Array.from(d, (b) => b.toString(16).padStart(2, '0')).join('')
}

function base64(bytes: Uint8Array): string {
  let s = ''
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000))
  return btoa(s)
}

/** Run the bundle's script (verified bytes): as a data: module where the runtime allows it, else through Function. */
async function evaluate(bytes: Uint8Array): Promise<Edge> {
  const g = globalThis as Record<string, unknown>
  delete g[GLOBAL]
  try {
    await import(`data:text/javascript;base64,${base64(bytes)}`)
  } catch (e) {
    log({ level: 'warn', event: 'verifier_data_import_refused', note: String(e).slice(0, 200) })
    new Function(new TextDecoder().decode(bytes))()
  }
  const edge = g[GLOBAL] as Edge | undefined
  delete g[GLOBAL]
  if (!edge || typeof edge.createEdgeHandler !== 'function') throw new Error('the bundle did not define the handler')
  return edge
}

async function load(): Promise<Handler> {
  const r = await fetch(URL_, { headers: { 'cache-control': 'no-cache' }, signal: AbortSignal.timeout(15000) })
  if (!r.ok) {
    await r.body?.cancel()
    throw new Error(`${URL_} answered ${r.status}`)
  }
  const bytes = new Uint8Array(await r.arrayBuffer())
  const got = await sha256Hex(bytes)
  if (got !== VERIFIER_SHA256) throw new Error(`the bundle's SHA-256 is ${got}, not the pinned ${VERIFIER_SHA256}`)
  const edge = await evaluate(bytes)
  if (edge.ENGINE_VERSION !== ENGINE) throw new Error(`the bundle runs engine ${edge.ENGINE_VERSION}, not ${ENGINE}`)
  log({ event: 'verifier_loaded', sha256: VERIFIER_SHA256.slice(0, 16) })
  return edge.createEdgeHandler({ site: SITE })
}

// One bundle per isolate; a failed load is retried at most once every 30 s
let handler: Promise<Handler> | null = null
let failedAt = 0

export default {
  fetch: withSupabase({ auth: 'user', errors: { detailed: false } }, async (req, ctx) => {
    if (!handler) {
      if (Date.now() - failedAt < 30000) return Response.json({ status: 503, code: 'verifier_unavailable', reason: 'The verifier is not loaded; retry shortly' }, { status: 503 })
      handler = load()
      handler.catch((e: unknown) => {
        log({ level: 'error', event: 'verifier_unavailable', note: String(e).slice(0, 300) })
        failedAt = Date.now()
        handler = null
      })
    }
    let run: Handler
    try {
      run = await handler
    } catch {
      return Response.json({ status: 503, code: 'verifier_unavailable', reason: 'The verifier could not be loaded or did not match its pinned hash' }, { status: 503 })
    }
    return run(req, ctx)
  }),
}
